/* Browser history and a visible directory for page → creator → work journeys. */
(function(root){
 function branch(rows,index,entry){return [...rows.slice(0,index+1),entry];}
 if(typeof module==='object')module.exports={branch};if(typeof document==='undefined')return;
 const key='folio-media-directory-v1';let rows=[],index=0,suspended=false,restoring=false,restoreSequence=0;
 try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.rows)){rows=saved.rows;index=Math.max(0,Math.min(saved.index,rows.length-1));}}catch{}
 function persist(){try{sessionStorage.setItem(key,JSON.stringify({rows,index}));}catch{}}
 function snapshot(){const creator=FolioCreators.snapshot();if(creator)return {type:'creator',label:creator.name,data:creator};const library=document.querySelector('#detail');if(library.open)return {type:'library',label:items.find(x=>x.id===currentId)?.title||'Library title',id:currentId,scroll:library.scrollTop};const hero=liveDialog.open&&liveDialog.querySelector('.media-hero'),media=hero&&FolioMediaInfo.forElement(hero);if(media)return {type:'media',label:media.title,media,scroll:liveDialog.scrollTop};return {type:'page',label:location.hash==='#search'?'Search':location.hash==='#library/insights'?'Insights':'Library',hash:location.hash,scroll:window.scrollY};}
 function stamp(){history.replaceState({...history.state,folioDirectory:rows[index]?.key},'',location.href);persist();}
 function before(){if(suspended||restoring)return;const state=snapshot();if(!rows[index]||history.state?.folioDirectory!==rows[index].key){rows=[{key:crypto.randomUUID(),state}];index=0;stamp();return;}if(state.type!=='page'||rows[index]?.state.type==='page'){rows[index]={key:rows[index]?.key||crypto.randomUUID(),state};stamp();}}
 function visit(state){if(suspended||restoring)return;const prior=rows[index]?.state;if(prior?.type===state.type&&(state.type==='library'?prior.id===state.id:state.type==='media'?prior.media?.id===state.media?.id:false)){rows[index].state=state;stamp();paint();return;}rows=branch(rows,index,{key:crypto.randomUUID(),state});index=rows.length-1;history.pushState({...history.state,folioDirectory:rows[index].key},'',location.href);persist();paint();}
 function update(){if(suspended||restoring||!rows[index])return;const state=snapshot();if(state.type!=='page'){rows[index].state=state;stamp();}paint();}
 function paint(){for(const container of document.querySelectorAll('#detail-content,#live-detail,#creator-dialog')){if(!container.closest('dialog')?.open&&container.tagName!=='DIALOG')continue;const dialog=container.closest('dialog');let nav=dialog.querySelector('.media-window-header .media-directory')||container.querySelector('.media-directory');if(!nav){const anchor=container.querySelector('.media-hero,.creator-header');if(!anchor)continue;nav=document.createElement('nav');nav.className='media-directory';nav.setAttribute('aria-label','Media directory');anchor.before(nav);}nav.innerHTML=`<button type="button" data-directory-step="-1" aria-label="Back in media directory" ${index===0?'disabled':''}>←</button><button type="button" data-directory-step="1" aria-label="Forward in media directory" ${index>=rows.length-1?'disabled':''}>→</button>${rows.slice(Math.max(0,index-3),index+1).map((row,i)=>{const at=Math.max(0,index-3)+i;return `<span aria-hidden="true">/</span><button type="button" class="directory-crumb" data-directory-index="${at}" ${at===index?'aria-current="page"':''}>${esc(row.state.label)}</button>`;}).join('')}`;let header=dialog.querySelector('.media-window-header');if(!header){header=document.createElement('header');header.className='media-window-header';dialog.prepend(header);}header.prepend(nav);let controls=dialog.querySelector('.detail-window-controls');if(!controls){const close=dialog.querySelector('.creator-close');if(close){controls=document.createElement('div');controls.className='detail-window-controls';controls.append(close);}}if(controls)header.append(controls);nav.querySelectorAll('[data-directory-step]').forEach(b=>b.onclick=()=>history.go(Number(b.dataset.directoryStep)));nav.querySelectorAll('[data-directory-index]').forEach(b=>b.onclick=()=>{const delta=Number(b.dataset.directoryIndex)-index;if(delta)history.go(delta);});}}
 async function restore(state){const sequence=++restoreSequence;restoring=true;try{for(const dialog of document.querySelectorAll('#detail[open],#live-detail[open],#creator-dialog[open]'))dialog.close();if(state.type==='creator')FolioCreators.restore(state.data);else if(state.type==='library'){openOwnedDetail(state.id);document.querySelector('#detail').scrollTop=state.scroll||0;}else if(state.type==='media'){await showLive(state.media);liveDialog.scrollTop=state.scroll||0;}else window.scrollTo({top:state.scroll||0,behavior:'instant'});}finally{if(sequence===restoreSequence){restoring=false;paint();}}}
 if(!rows.length||!rows.some(r=>r.key===history.state?.folioDirectory)){rows=[{key:crypto.randomUUID(),state:snapshot()}];index=0;stamp();}else index=rows.findIndex(r=>r.key===history.state.folioDirectory);
 const openLibrary=openOwnedDetail;openOwnedDetail=function(id){before();const result=openLibrary(id);visit(snapshot());return result;};
 const openMedia=showLive;showLive=async function(media){before();await openMedia(media);if(liveDialog.open&&liveDialog.querySelector('.media-hero'))visit(snapshot());};
 window.addEventListener('popstate',()=>{const at=rows.findIndex(r=>r.key===history.state?.folioDirectory);if(at>=0){index=at;persist();restore(rows[index].state);}else{rows=[{key:crypto.randomUUID(),state:snapshot()}];index=0;stamp();}});
 window.addEventListener('hashchange',()=>{if(restoring||suspended)return;const state=snapshot();if(state.type==='page'){rows=[{key:crypto.randomUUID(),state}];index=0;stamp();}});
 root.FolioDirectory={before,visit:()=>visit(snapshot()),update,back:()=>{if(index>0)history.back();},suspend:value=>{suspended=value;if(!value)update();}};
})(globalThis);
